import json, os
for task in sorted(os.listdir('results/plan_c/')):
    td = os.path.join('results/plan_c/', task)
    if not os.path.isdir(td): continue
    # Count in episode_summary.jsonl
    sp = os.path.join(td, 'episode_summary.jsonl')
    ep = os.path.join(td, 'episodes.jsonl')
    s_count, e_count = 0, 0
    if os.path.isfile(sp):
        with open(sp) as f:
            for line in f:
                if line.strip(): s_count += 1
    if os.path.isfile(ep):
        with open(ep) as f:
            for line in f:
                if line.strip():
                    d = json.loads(line)
                    if 'always_internal' in d and 'always_deterministic' in d:
                        e_count += 1
    print(f'{task}: summary={s_count} episodes={e_count}')
